using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

/// <summary>
/// MCP tools that wrap a weather REST API.
/// Instance methods receive constructor-injected services (like HttpClient)
/// each time the tool is invoked — the SDK creates a new instance per call.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _http;

    // The SDK resolves constructor parameters from the DI container.
    // IHttpClientFactory is registered in Program.cs; the SDK sees the
    // HttpClient parameter and resolves it via DI.
    public WeatherTools(HttpClient http)
    {
        _http = http;
    }

    [McpServerTool(Name = "get_current_weather", ReadOnly = true),
     Description("Get current weather for a city. Returns temperature, humidity, and conditions.")]
    public async Task<string> GetCurrentWeather(
        [Description("City name, e.g. 'London' or 'New York'")] string city,
        [Description("Temperature unit: 'celsius' or 'fahrenheit' (default: celsius)")] string units = "celsius",
        CancellationToken cancellationToken = default)
    {
        var url = $"https://api.weatherapi.com/v1/current.json?q={Uri.EscapeDataString(city)}";
        var response = await _http.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        using var doc = JsonDocument.Parse(json);

        var current = doc.RootElement.GetProperty("current");
        var tempKey = units == "fahrenheit" ? "temp_f" : "temp_c";
        var temp = current.GetProperty(tempKey).GetDouble();
        var condition = current.GetProperty("condition").GetProperty("text").GetString();
        var humidity = current.GetProperty("humidity").GetInt32();

        return $"{city}: {temp}°{(units == "fahrenheit" ? "F" : "C")}, {condition}, Humidity: {humidity}%";
    }

    [McpServerTool(Name = "get_forecast", ReadOnly = true),
     Description("Get a multi-day weather forecast for a city.")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        [Description("Number of forecast days (1-3)")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        days = Math.Clamp(days, 1, 3);
        var url = $"https://api.weatherapi.com/v1/forecast.json?q={Uri.EscapeDataString(city)}&days={days}";
        var response = await _http.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        using var doc = JsonDocument.Parse(json);

        var forecastDays = doc.RootElement
            .GetProperty("forecast")
            .GetProperty("forecastday")
            .EnumerateArray();

        var lines = new List<string> { $"Forecast for {city}:" };
        foreach (var day in forecastDays)
        {
            var date = day.GetProperty("date").GetString();
            var dayInfo = day.GetProperty("day");
            var maxC = dayInfo.GetProperty("maxtemp_c").GetDouble();
            var minC = dayInfo.GetProperty("mintemp_c").GetDouble();
            var cond = dayInfo.GetProperty("condition").GetProperty("text").GetString();
            lines.Add($"  {date}: {minC}-{maxC}°C, {cond}");
        }

        return string.Join('\n', lines);
    }
}

